/* ------------------------------------------------------------------ */
/* App shell                                                            */
/* ------------------------------------------------------------------ */
export default function App() {
  const [scrolled, setScrolled] = useState(false);
  const [active, setActive] = useState("home");
  const [bannerOpen, setBannerOpen] = useState(true);
  const [buyModalOpen, setBuyModalOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const ids = [...NAV_LINKS.map((l) => l.id), "buy"];
    const sections = ids.map((id) => document.getElementById(id)).filter(Boolean);
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => { if (e.isIntersecting) setActive(e.target.id); });
      },
      { rootMargin: "-45% 0px -45% 0px" }
    );
    sections.forEach((s) => io.observe(s));
    return () => io.disconnect();
  }, []);

  const navigate = (id) => {
    document.getElementById(id)?.scrollIntoView({ behavior: "smooth" });
  };

  const openBuyModal = () => setBuyModalOpen(true);

  return (
    <div style={{ background: PAPER }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500&family=Inter:wght@400;500;600&family=Manrope:wght@500;600;700&display=swap');
        * { box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        @keyframes floaty { 0%,100% { transform: translateY(0px); } 50% { transform: translateY(-14px); } }
        @keyframes bookBob { 0%,100% { transform: translateY(0px) rotateY(-18deg) rotateX(8deg); } 50% { transform: translateY(-10px) rotateY(-18deg) rotateX(8deg); } }
        @keyframes twinkle { 0%,100% { opacity: 0.2; } 50% { opacity: 0.9; } }
        @keyframes pageFade { from { opacity: 0; transform: translateX(10px); } to { opacity: 1; transform: translateX(0); } }
        @keyframes modalIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        @keyframes bannerIn { from { opacity: 0; transform: translateY(-100%); } to { opacity: 1; transform: translateY(0); } }
        @keyframes wave { 0%, 100% { transform: rotate(0deg); } 25% { transform: rotate(14deg); } 75% { transform: rotate(-10deg); } }
        @keyframes ctaPulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(34,197,94,0.55); } 50% { box-shadow: 0 0 0 7px rgba(34,197,94,0); } }
        @keyframes glowPulse { 0%, 100% { box-shadow: 0 0 0 1px rgba(96,165,250,0.35), 0 14px 34px -10px rgba(37,99,235,0.6); } 50% { box-shadow: 0 0 0 1px rgba(96,165,250,0.55), 0 18px 44px -8px rgba(37,99,235,0.85); } }
        ::selection { background: rgba(212,175,55,0.3); }
        input:focus, textarea:focus { border-color: ${TEAL} !important; }
        @media (prefers-reduced-motion: reduce) {
          *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
        }
      `}</style>

      <div className="fixed top-0 left-0 right-0 z-50">
        {bannerOpen && <AzadiBanner onClose={() => setBannerOpen(false)} onClaim={() => { setBannerOpen(false); navigate("buy"); }} />}
        <Nav scrolled={scrolled} onNavigate={navigate} activeSection={active} />
      </div>
      <Hero onNavigate={navigate} bannerOpen={bannerOpen} />
      <AboutBook />
      <Chapters />
      <FreeSample onNavigate={navigate} />
      <Worksheets onLockedClick={openBuyModal} />
      <AuthorSection />
      <Reviews />
      <FAQ />
      <BuyNow onBuyClick={openBuyModal} />
      <Contact />
      {buyModalOpen && <BuyModal onClose={() => setBuyModalOpen(false)} />}
    </div>
  );
}
